def fizzbuzz(n):
    if n % 3 == 0:
        return "Fizz"
    if n % 5 == 0:
        return "Buzz"
    if n % 15 == 0:
        return "FizzBuzz"
    return str(n)

from fizzbuzz import fizzbuzz


def test_numbers():
    assert [fizzbuzz(i) for i in (1, 3, 5, 15, 30)] == ["1", "Fizz", "Buzz", "FizzBuzz", "FizzBuzz"]

